solution.solution.c:
#include <math.h>
#include <time.h>

static time_t noon(int year, int month, int day, struct tm *out)
{
    struct tm t = {0};
    t.tm_year = year - 1900;
    t.tm_mon = month - 1;
    t.tm_mday = day;
    t.tm_hour = 12;
    t.tm_isdst = -1;
    time_t r = mktime(&t);
    if (out) *out = t;
    return r;
}

int add_days(int *year, int *month, int *day, int days)
{
    struct tm t;
    if (noon(*year, *month, *day + days, &t) == (time_t)-1) return -1;
    *year = t.tm_year + 1900;
    *month = t.tm_mon + 1;
    *day = t.tm_mday;
    return 0;
}

long days_between(int y1, int m1, int d1, int y2, int m2, int d2)
{
    double secs = difftime(noon(y2, m2, d2, NULL), noon(y1, m1, d1, NULL));
    return lround(secs / 86400.0);
}

int last_day_of_month(int year, int month)
{
    struct tm t;
    noon(year, month + 1, 0, &t);
    return t.tm_mday;
}

unitTests:
TEST("adding days across months and years") { int y = 2026, m = 1, d = 31; CHECK_EQ(add_days(&y, &m, &d, 30), 0); CHECK_EQ(y, 2026); CHECK_EQ(m, 3); CHECK_EQ(d, 2); y = 2026; m = 12; d = 25; add_days(&y, &m, &d, 10); CHECK_EQ(y, 2027); CHECK_EQ(m, 1); CHECK_EQ(d, 4); }
TEST("going back") { int y = 2026, m = 3, d = 1; add_days(&y, &m, &d, -1); CHECK_EQ(m, 2); CHECK_EQ(d, 28); y = 2024; m = 3; d = 1; add_days(&y, &m, &d, -1); CHECK_EQ(d, 29); }
TEST("days between") { CHECK_EQ((int)days_between(2026, 1, 1, 2027, 1, 1), 365); CHECK_EQ((int)days_between(2024, 1, 1, 2025, 1, 1), 366); CHECK_EQ((int)days_between(2026, 11, 20, 2026, 12, 25), 35); CHECK_EQ((int)days_between(2026, 12, 25, 2026, 11, 20), -35); CHECK_EQ((int)days_between(2026, 3, 1, 2026, 4, 1), 31); }
TEST("last day of the month") { CHECK_EQ(last_day_of_month(2026, 2), 28); CHECK_EQ(last_day_of_month(2024, 2), 29); CHECK_EQ(last_day_of_month(2026, 4), 30); CHECK_EQ(last_day_of_month(2026, 12), 31); }

